import{_ as s,o as a,c as t,a2 as e}from"./chunks/framework.CqGS6Fr9.js";const E=JSON.parse('{"title":"Размещение и запуск","description":"","frontmatter":{"pageId":"admins/hosting","contentRevision":1},"headers":[],"relativePath":"ru/admins/hosting.md","filePath":"ru/admins/hosting.md"}'),n={name:"ru/admins/hosting.md"};function h(l,i,k,p,r,d){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="размещение-и-запуск" tabindex="-1">Размещение и запуск <a class="header-anchor" href="#размещение-и-запуск" aria-label="Permalink to &quot;Размещение и запуск&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Сервер — ASP.NET Core 10 с gRPC/HTTP2, REST и SQLite. Для запуска исходников нужен SDK из global.json; для framework-dependent релиза — соответствующий runtime. Постоянно сохраняй весь Server:DataDir, а не только БД.</p><p>Контейнерный пример в репозитории публикует 25560:25560 и монтирует ./data в /data. Перед запуском заполни секреты окружения. Для своего build используй deploy/Dockerfile. Вне Docker запускай исполняемый файл релиза из стабильного рабочего каталога: относительные пути вычисляются от него.</p><p>Прокси обязан пропускать HTTP/2/gRPC и долгие потоки, а не только страницу панели. Проверь сохранение и live-поток с внешнего клиента. Останавливай штатно с предупреждением игроков.</p><h3 id="минимальныи-запуск-из-исходников" tabindex="-1">Минимальный запуск из исходников <a class="header-anchor" href="#минимальныи-запуск-из-исходников" aria-label="Permalink to &quot;Минимальный запуск из исходников&quot;">​</a></h3><p>Установи SDK из global.json, собери сервер и создай отдельный рабочий каталог данных. Следующие команды выполняются из корня репозитория; парольный вход включён только для примера. В рабочем сервере используй собственные длинные секреты из окружения, не фиксируй их в Git.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows / PowerShell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rimlink__Server__DataDir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./data&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rimlink__Auth__AllowPassword</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;true&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rimlink__Auth__AdminLogins__0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;admin&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rimlink.Server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rimlink__Server__DataDir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Rimlink__Auth__AllowPassword</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Rimlink__Auth__AdminLogins__0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Rimlink.Server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><h3 id="контеинер" tabindex="-1">Контейнер <a class="header-anchor" href="#контеинер" aria-label="Permalink to &quot;Контейнер&quot;">​</a></h3><p>Из корня репозитория настрой секреты окружения, затем выполни <code>docker compose -f deploy/docker-compose.yml up -d</code>. Проверь <code>docker compose -f deploy/docker-compose.yml logs --tail=100</code>. Пример использует latest; перед рабочим запуском закрепи проверенный тег/ digest. Не запускай вместе с bare-процессом на том же DataDir. Штатная остановка: <code>docker compose -f deploy/docker-compose.yml down</code>; не добавляй удаление томов.</p><h3 id="минимальная-конфигурация-и-проверка" tabindex="-1">Минимальная конфигурация и проверка <a class="header-anchor" href="#минимальная-конфигурация-и-проверка" aria-label="Permalink to &quot;Минимальная конфигурация и проверка&quot;">​</a></h3><p>Для framework-dependent пакета файл appsettings.json в каталоге сервера содержит секции верхнего уровня; внешняя оболочка Rimlink в JSON не нужна:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25560</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;DataDir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Auth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;AllowPassword&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;AdminLogins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}}</span></span></code></pre></div><p>Запускай пакет через <code>dotnet Rimlink.Server.dll</code> из стабильного каталога. TLS включён по умолчанию: для первого подключения сверяй fingerprint по доверенному каналу; для публичного сертификата укажи Tls:CertificatePath и Tls:KeyPath (PEM). Открой TCP 25560 на сервере и маршрутизаторе только для нужной сети. Ожидаемый результат: сервер слушает порт, /health отвечает, клиент успешно сохраняет и повторно загружает колонию. Панель без успешного игрового подключения ещё не доказывает работу HTTP/2 прокси.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Один DataDir не должен обслуживаться несколькими серверами одновременно. Не копируй активную БД и сейвы произвольными независимыми копированиями. TLS обязателен по умолчанию; HTTP только для изолированной разработки.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./configuration">Справочник конфигурации</a></li><li><a href="./monitoring">Мониторинг и журнал событий</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li></ul>`,20)])])}const g=s(n,[["render",h]]);export{E as __pageData,g as default};
